import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static long[] p;
    static long val(int x,int y, int n){
        return 2*p[x]+p[x+2*y]+3*p[3*n-2*x-y];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while(t-->0){
            int n = sc.nextInt();
            int m = 3*n;
            long[] a = new long[m];
            for(int i=0;i<m;i++)
            {
                a[i] = sc.nextLong();
            }
            Arrays.sort(a);
            for(int i=0;i<3*n/2;i++){
                long temp = a[i];
                a[i] = a[3*n-1-i];
                a[3*n-1-i] = temp;
            }
            p = new long[m+1];
            for(int i=0;i<m;i++){
                p[i+1] = p[i]+a[i];
            }
            long ans = 0;
            for(int x=0;x<=n;x++){
                int low =0,high =n-x;
                while(low<high){
                    int mid = (low+high)/2;
                    if(val(x,mid,n)<val(x,mid+1,n)){
                        low = mid+1;
                    }
                    else{
                        high = mid;
                    }
                }
                ans = Math.max(ans,val(x,low,n));
            }
            System.out.println(ans);
        }
	}
}
